corrected_code:
const express = require('express');
const { activeSpanCache } = require('../telemetry/processor');

const app = express();
app.use(express.json());

app.post('/api/telemetry/spans/inspect', (req, res) => {
  const { spanId } = req.body;
  if (!spanId) {
    return res.status(400).json({ error: 'Missing spanId' });
  }

  const span = activeSpanCache.get(spanId);
  if (!span) {
    return res.status(404).json({ error: 'Span not found in active telemetry processor buffer' });
  }

  // Ensure span's tenant attribute matches authenticated client's tenant
  if (span.attributes['tenant.id'] !== req.user.tenantId) {
    return res.status(403).json({ error: 'Access denied: Span belongs to another tenant' });
  }

  return res.json({
    spanId: span.spanContext().spanId,
    traceId: span.spanContext().traceId,
    name: span.name,
    attributes: span.attributes
  });
});

module.exports = app;
